// 2. app/users/[id]/page.tsx (Server Component)
import { getPrivateUserData } from './db-service';
import { ClientAvatarMenu } from './ClientAvatarMenu';

export default async function UserProfilePage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params; // Dynamic APIs là async trong Next.js 16
  const user = await getPrivateUserData(id);
  if (!user) return null;

  return (
    <div>
      <h1>Welcome {user.name}</h1>
      <ClientAvatarMenu user={{ name: user.name, avatarUrl: user.avatarUrl }} />
    </div>
  );
}

