// app/lib/products.ts
import { cacheLife, cacheTag } from 'next/cache';

export async function getProduct(id: string) {
  'use cache';
  cacheLife('hours');
  cacheTag('products', `product:${id}`);
  return db.product.findUnique({ where: { id } });
}

// app/products/[id]/page.tsx
export default async function Page({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  return <ProductDetails product={await getProduct(id)} />;
}

'use server';
import { updateTag } from 'next/cache';
import { z } from 'zod';

const RenameProduct = z.object({ id: z.string().min(1), name: z.string().trim().min(1) });

export async function renameProduct(formData: FormData) {
  const actor = await requireUser();
  const input = RenameProduct.parse({ id: formData.get('id'), name: formData.get('name') });
  await assertCanEditProduct(actor, input.id);
  await db.product.update({ where: { id: input.id }, data: { name: input.name } });

  updateTag(`product:${input.id}`);
  updateTag('products');
}

